def get_annotation(node):
    """return the annotation node of the __init__ argument assigned to the
    given AssignAttr node (``self.a = a``), or None
    """
    init_method = node.parent.parent
    value = node.parent.value if hasattr(node.parent, "value") else None
    if not isinstance(init_method, astroid.FunctionDef) or not isinstance(
        value, astroid.Name
    ):
        return None
    args = init_method.args
    names = [arg.name for arg in args.args]
    annotations = args.annotations
    if value.name not in names or len(names) != len(annotations):
        return None
    return annotations[names.index(value.name)]


def infer_node(node):
    """return the types of an AssignAttr node, preferring type annotations"""
    ann = get_annotation(node)
    if ann is not None:
        return {ann}
    return set(node.infer())
